import { omitTopLevel, validateCookieBindings } from "../policy/cookies.js";
export function projectHttpCookies(facts, policy, source) {
    const bindings = validateCookieBindings(facts, policy);
    return {
        endpoints: source.endpoints.map((endpoint) => {
            const omittedInput = new Set(bindings
                .filter((binding) => binding.protectedPaths.has(endpoint.path))
                .map((binding) => binding.binding.input));
            const omittedOutput = new Set(bindings.flatMap((binding) => binding.binding.issue
                .filter((issue) => issue.path === endpoint.path)
                .flatMap((issue) => [issue.value, issue.expires])));
            return {
                ...endpoint,
                input: omittedInput.size === 0 ? endpoint.input : omitTopLevel(endpoint.input, omittedInput),
                output: omittedOutput.size === 0 ? endpoint.output : omitTopLevel(endpoint.output, omittedOutput),
            };
        }),
        appWide: source.appWide,
    };
}
